package connect

// ResultOf reports the winner of a game of Hex / Polygon.
//
// The board is a parallelogram of hexagonal cells. Player "O" connects the
// top edge to the bottom edge, and player "X" connects the left edge to the
// right edge. The first player to form such a connection wins. If neither
// player has a connection the result is "".
//
// The board is supplied as a slice of strings; each string is one row of the
// parallelogram (the leading spaces used for readability are irrelevant and
// may already have been stripped).
func ResultOf(lines []string) (string, error) {
	if len(lines) == 0 {
		return "", nil
	}

	rows := len(lines)
	cols := len(lines[0])
	if cols == 0 {
		return "", nil
	}

	board := make([][]byte, rows)
	for i, line := range lines {
		board[i] = []byte(line)
	}

	// Player "O" connects the top edge to the bottom edge.
	if connects(board, 'O', rows, cols,
		func(r, c int) bool { return r == 0 },
		func(r, c int) bool { return r == rows-1 },
	) {
		return "O", nil
	}

	// Player "X" connects the left edge to the right edge.
	if connects(board, 'X', rows, cols,
		func(r, c int) bool { return c == 0 },
		func(r, c int) bool { return c == cols-1 },
	) {
		return "X", nil
	}

	return "", nil
}

// connects reports whether the given player has a connected path of their own
// pieces running from the start edge to the goal edge. It performs a breadth
// first search starting from every one of the player's pieces that sits on the
// start edge and succeeds as soon as any of them reaches the goal edge.
func connects(board [][]byte, player byte, rows, cols int,
	startEdge, goalEdge func(int, int) bool) bool {

	// piece reports the piece at (r, c), or 0 when the cell is out of bounds.
	piece := func(r, c int) byte {
		if r < 0 || r >= rows || c < 0 || c >= len(board[r]) {
			return 0
		}
		return board[r][c]
	}

	visited := make([][]bool, rows)
	for i := range visited {
		visited[i] = make([]bool, cols)
	}

	queue := make([][2]int, 0, rows*cols)
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if piece(r, c) == player && startEdge(r, c) {
				visited[r][c] = true
				queue = append(queue, [2]int{r, c})
			}
		}
	}

	for len(queue) > 0 {
		r, c := queue[0][0], queue[0][1]
		queue = queue[1:]

		if goalEdge(r, c) {
			return true
		}

		for _, n := range neighbors(r, c, rows, cols) {
			nr, nc := n[0], n[1]
			if !visited[nr][nc] && piece(nr, nc) == player {
				visited[nr][nc] = true
				queue = append(queue, [2]int{nr, nc})
			}
		}
	}

	return false
}

// neighbors returns the in-bounds neighbours of cell (r, c) in the parallelogram.
//
// The board is a sheared grid: each row is shifted relative to the one above
// it, so the six hexagonal neighbours of (r, c) are the two cells in the same
// row, the two cells in the row above, and the two cells in the row below.
func neighbors(r, c, rows, cols int) [][2]int {
	candidates := [][2]int{
		{r, c - 1}, {r, c + 1},
		{r - 1, c}, {r - 1, c + 1},
		{r + 1, c}, {r + 1, c - 1},
	}

	n := make([][2]int, 0, 6)
	for _, p := range candidates {
		if p[0] >= 0 && p[0] < rows && p[1] >= 0 && p[1] < cols {
			n = append(n, p)
		}
	}
	return n
}
